public class GcdLcm {
    static int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int a = in.nextInt();
        int b = in.nextInt();
        int g = gcd(a, b);
        System.out.println("gcd: " + g);
        System.out.println("lcm: " + (a / g * b));
    }
}

