    }

    double average() const {
        return (double) total / count;
    }

    char grade() const {
        double avg = average();
        if (avg >= 90) return 'A';
        if (avg >= 75) return 'B';
        if (avg >= 50) return 'C';
        return 'F';
    }

    string getName() const { return name; }
};

int main() {
    string name;
    cin >> name;
    Student s(name);
    for (int i = 0; i < 3; i++) {
        int mark;
        cin >> mark;
        s.addMark(mark);
    }
    printf("%s average %.1f grade %c\n", s.getName().c_str(), s.average(), s.grade());
    return 0;
}

